#include <cstdio>
#include <vector>

using namespace std;

const int NMAX = 100010;
const int MOD = 1000000007;

int m;
int f[NMAX];
vector<int> fact[NMAX];

int Power(int x, int y) {
    int ret = 1;
    while (y) {
        if (y & 1) ret = 1LL * ret * x % MOD;
        x = 1LL * x * x % MOD;
        y >>= 1;
    }
    return ret;
}

int inv(int x) {
    return Power(x, MOD - 2);
}

int calc(int a, int b) {
    int prime[10], cnt = 0;
    int tmpa = a / b;

    for (int i = 2; 1LL * i * i <= tmpa; ++i) {
        if (tmpa % i == 0) {
            prime[cnt++] = i;
            while (tmpa % i == 0) tmpa /= i;
        }
    }
    if (tmpa > 1) prime[cnt++] = tmpa;

    int sum = 0;
    for (int mask = 0; mask < (1 << cnt); ++mask) {
        int mult = 1;
        int sign = 1;
        for (int j = 0; j < cnt; ++j) {
            if (mask & (1 << j)) {
                mult *= prime[j];
                sign = -sign;
            }
        }
        sum += (m / b) / mult * sign;
    }
    return sum;
}

int main() {
    scanf("%d", &m);

    for (int i = 1; i <= m; ++i) {
        for (int j = i * 2; j <= m; j += i) {
            fact[j].push_back(i);
        }
    }

    const int invM = inv(m);
    f[1] = 1;

    for (int i = 2; i <= m; ++i) {
        int sum = 0;
        for (int j : fact[i]) {
            sum = (sum + 1LL * f[j] * calc(i, j) % MOD * invM) % MOD;
        }

        int denominator = m - calc(i, i);
        f[i] = 1LL * (1 + sum) * m % MOD * inv(denominator) % MOD;
    }

    int answer = 0;
    for (int i = 1; i <= m; ++i) {
        answer = (answer + 1LL * f[i] * invM) % MOD;
    }

    printf("%d\n", answer);
    return 0;
}

